// ---------------------------------------------------------------- hand-written

// far calls through a pointer: the functions the program stores as pointers (a segment in any of the
// three encodings: Ghidra's, the image's, the loaded program's)
void asm_far_call(u16 seg, u16 off)
{
  if (off == 0x0898 && (seg == 0x119e || seg == 0x019e || seg == 0x296a)) { a_119e_0898(); return; }
  if (off == 0x0be6 && (seg == 0x119e || seg == 0x019e || seg == 0x296a)) { a_119e_0be6(); return; }
  if (off == 0x0a26 && (seg == 0x119e || seg == 0x019e || seg == 0x296a)) { a_119e_0a26(); return; }
  if (off == 0x037e && (seg == 0x290b || seg == 0x190b || seg == 0x40d7)) { a_290b_037e(); return; }
  if (off == 0x039c && (seg == 0x290b || seg == 0x190b || seg == 0x40d7)) { a_290b_039c(); return; }
  if (off == 0x03d2 && (seg == 0x290b || seg == 0x190b || seg == 0x40d7)) { a_290b_03d2(); return; }
  if (off == 0x03e2 && (seg == 0x290b || seg == 0x190b || seg == 0x40d7)) { a_290b_03e2(); return; }
  asm_unknown_call(seg, off);
}














































